package mrpapermoon.whisper.contacts.dbimport androidx.room.Daoimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Queryimport kotlinx.coroutines.flow.Flow@Daointerface ContactDao {	@Insert(onConflict = OnConflictStrategy.REPLACE)	suspend fun insert(user: ContactEntity)	@Query("SELECT * FROM ${ContactEntity.TABLE_NAME} WHERE whispererId = :whispererId")	suspend fun getUser(whispererId: String): ContactEntity?	@Query("SELECT * FROM ${ContactEntity.TABLE_NAME}")	fun getAllUsers(): Flow<List<ContactEntity>>}